  const b = screenWelfare(raw);
  const hits = [...a.hits || [], ...b.hits];
  const tier = RANK[a.tier] >= RANK[b.tier] ? a.tier : b.tier;
  return { tier, categories: [.../* @__PURE__ */ new Set([...a.categories || [], ...b.categories])], hits };
