      const opts2 = [{ text: cap(words(n)), right: true }, ...[n2, n3, n4].map((v) => ({ text: cap(words(v)), right: false, why: `Those words say ${commas(v)}. Say the number ${commas(n)} again: thousands, then hundreds, then tens and ones.` }))];
