var fam14 = (def) => family({ reviewed: false, ...def });
var uniq5 = (...a) => new Set(a.map((x) => typeof x === "number" ? round(x, 6) : x)).size === a.length;
var shuffle9 = (a) => {
  const b = [...a];
  for (let i = b.length - 1; i > 0; i--) {
    const j = randInt(0, i);
    [b[i], b[j]] = [b[j], b[i]];
  }
  return b;
};
var TRIPLES2 = [[3, 4, 5], [5, 12, 13], [8, 15, 17], [7, 24, 25], [20, 21, 29], [6, 8, 10]];
